{
  "schema_version": "text-task-plan-v2",
  "decomposition_reason": "任务为四个独立申请的规则审核，规则简单且材料短小，拆分会增加交接与汇总开销而收益有限；单节点可直接完成全部审核并输出最终说明。",
  "nodes": [
    {
      "node_id": "answer",
      "node_type": "generation",
      "prompt_template": "请按以下虚构资料馆规则审核四个申请，并给出可直接发送给申请人的简短说明。规则：公开目录任何人可查；扫描件仅对持有效会员证者提供，但未满 16 岁还须监护人书面同意；原件须提前两个工作日预约且仅在馆内查阅，会员资格不替代预约。申请甲：非会员，只查公开目录。乙：15 岁，会员证有效，申请扫描件，监护人同意尚未收到。丙：20 岁，会员证有效，希望今天借走原件，未预约。丁：17 岁，会员证有效，申请扫描件。不得添加收费、证件类别或其他规则。\n\n最终交付必须满足：\n四个申请分别给出正确结论及相应规则理由。\n乙应待监护人书面同意；丙同时涉及未预约和不能外借，不遗漏其中之一。\n说明清楚友好，不添加材料未列出的限制或收费。\n\n请直接输出最终说明正文，分别呈现甲、乙、丙、丁四个申请的结论及规则理由，语言清楚友好。",
      "parents": [],
      "contract": {
        "objective": "审核四个申请并输出可直接发送给申请人的简短说明，分别给出结论及规则理由。",
        "inputs": {},
        "output": {
          "format": "text",
          "fields": {
            "text": "最终交付的简短说明正文，分别呈现甲、乙、丙、丁四个申请的结论及规则理由。"
          }
        },
        "capability": {
          "difficulty": "low",
          "risk": "low",
          "input_budget_tokens": 16384,
          "expected_output_tokens": 1000
        },
        "checks": [
          "四个申请分别给出正确结论及相应规则理由。",
          "乙应待监护人书面同意；丙同时涉及未预约和不能外借，不遗漏其中之一。",
          "说明清楚友好，不添加材料未列出的限制或收费。"
        ],
        "covers": [0, 1, 2],
        "execution": "text-model",
